DROP TABLE IF EXISTS "seaman";

CREATE TABLE "seaman" (
    "seamancode"	INT,
    "age"	INT,
    "certificate"	VARCHAR(512),
    "day_remains"	INT,
    "edu_level"	VARCHAR(512),
    "end_date"	VARCHAR(512),
    "experience"	VARCHAR(512),
    "gender"	VARCHAR(512),
    "is_active_employee"	VARCHAR(512),
    "last_location"	VARCHAR(512),
    "last_position"	VARCHAR(512),
    "name"	VARCHAR(512),
    "no"	INT,
    "phone_number_1"	VARCHAR(512),
    "phone_number_2"	VARCHAR(512),
    "phone_number_3"	INT,
    "phone_number_4"	VARCHAR(512),
    "seafarercode"	INT,
    "start_date"	VARCHAR(512),1
    "status"	VARCHAR(512),
    "birthdate"	VARCHAR(512),
    "birthplace"	VARCHAR(512),
    "day_elapsed"	INT,
    "fleet"	VARCHAR(512),
    "last_vesselid"	VARCHAR(512),
    "pic_crewing"	VARCHAR(512),
    "prevlocation"	VARCHAR(512),
    "prevposition"	VARCHAR(512),
    "created_at"	VARCHAR(512),
    "updated_at"	VARCHAR(512),
    "is_talent"	VARCHAR(512)
);

